/// A tessellated body whose height its construction does not state stays
/// widened by its chord deviation (#393): a horizontal pipe under the
/// floor whose round top touches it may rise into the band, and without
/// its exact boundary nothing narrows that, so the room stays undecided.
#[test]
fn with_geometry_an_uncertified_round_top_touching_the_floor_stays_undecided() {
    let case = Case::new("geometry-free-floor-uncertified");
    // Pipe #69, radius 0.1 along x at z = 3.6: its axis placement turns
    // the circle's plane upright.
    let pipe = "#60=IFCCARTESIANPOINT((-2.,0.,3.6));\n\
                #61=IFCDIRECTION((1.,0.,0.));\n\
                #62=IFCDIRECTION((0.,1.,0.));\n\
                #63=IFCAXIS2PLACEMENT3D(#60,#61,#62);\n\
                #64=IFCLOCALPLACEMENT($,#63);\n\
                #65=IFCCIRCLEPROFILEDEF(.AREA.,$,$,0.1);\n\
                #66=IFCEXTRUDEDAREASOLID(#65,#2,#4,4.);\n\
                #67=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#66));\n\
                #68=IFCPRODUCTDEFINITIONSHAPE($,$,(#67));\n\
                #69=IFCPIPESEGMENT('0000000000000000000069',$,$,$,$,#64,#68,$,$);\n";
    let model = room_over_a_curved_slab(3.0, pipe);
    let (output, result) = turning_circle(&case, &model, &["--no-exact-boundaries"]);
    assert_eq!(output.status.code(), Some(4), "{}", stderr(&output));
    assert_eq!(finding_messages(&result), [], "{result:#}");
    let message = result["report"]["not_evaluated"][0]["message"]
        .as_str()
        .unwrap_or_default();
    assert!(message.contains("not exact"), "{:#}", result["report"]);
    // Its exact boundary bounds its extent in closed form: the top stays
    // at the floor and the room decides.
    let (output, result) = turning_circle(&case, &model, &[]);
    assert_eq!(output.status.code(), Some(0), "{}", stderr(&output));
    assert_eq!(finding_messages(&result), [], "{result:#}");
}

/// Sanitary terminal `#{first + 9}` whose `Body` is an open shell (a face
/// set of five quads spanning `min..max`, its top left out), as instances
/// `first..first + 9`: what it occupies is no closed solid's.
fn open_terminal(first: u32, min: [f64; 3], max: [f64; 3]) -> String {
    let shell = face_set_box(first, min, max, Faces::OpenTop);
    let wall = format!("#{}=IFCWALL(", first + 9);
    let (faces, product) = shell.split_once(&wall).unwrap();
    let (attributes, _) = product.rsplit_once(",$);").unwrap();
    format!("{faces}#{}=IFCFLOWTERMINAL({attributes});\n", first + 9)
}

/// The not-evaluated messages of a report.
fn not_evaluated_messages(result: &Value) -> Vec<String> {
    result["report"]["not_evaluated"]
        .as_array()
        .map(|outcomes| {
            outcomes
                .iter()
                .map(|outcome| outcome["message"].as_str().unwrap_or_default().to_owned())
                .collect()
        })
        .unwrap_or_default()
}

/// #401: a sanitary terminal authored as an open shell standing on the
/// floor has no inside, so what it occupies in the band was undecided and
/// left every room it stands in not evaluated. Its body lies within the
/// hull of its vertices, a possible obstacle: a room holding the circle
/// beside that hull passes, a room the circle fits only where the
/// terminal stands stays not evaluated naming it (no absence rests on a
/// bound), and a room too small without it fails.
#[test]
fn with_geometry_an_open_terminal_is_bounded_by_its_vertices() {
    let case = Case::new("geometry-free-floor-open-terminal");
    let space = "IFCSPACE('GID',$,$,$,$,PL,REP,$,.ELEMENT.,$,$)";
    let room = |side: f64, terminal: ([f64; 3], [f64; 3])| {
        model_with(&format!(
            "{}{}",
            placed_box(10, [side / 2.0, side / 2.0, 0.0], [side, side, 3.0], space),
            open_terminal(40, terminal.0, terminal.1),
        ))
    };
    // In the corner of a 3 m room: the circle fits beside it.
    let corner = ([0.1, 0.1, 0.0], [0.7, 0.8, 0.9]);
    let (output, result) = turning_circle(&case, &room(3.0, corner), &[]);
    assert_eq!(output.status.code(), Some(0), "{}", stderr(&output));
    assert_eq!(finding_messages(&result), [], "{result:#}");
    assert_eq!(not_evaluated_messages(&result), Vec::<String>::new());
    let integrity = result["integrity"].to_string();
    assert!(integrity.contains("shape.open-surface"), "{integrity}");
    // In the middle of a 1.6 m room: the circle fits only where it stands.
    let middle = ([0.6, 0.6, 0.0], [1.0, 1.0, 0.9]);
    let (output, result) = turning_circle(&case, &room(1.6, middle), &[]);
    assert_eq!(output.status.code(), Some(4), "{}", stderr(&output));
    assert_eq!(finding_messages(&result), [], "{result:#}");
    let messages = not_evaluated_messages(&result);
    assert!(
        messages.len() == 1
            && messages[0].contains("bounded rather than measured")
            && messages[0].contains("/#49"),
        "{messages:?}"
    );
    // A 1.4 m room holds no 1.5 m circle with or without it.
    let (output, result) = turning_circle(&case, &room(1.4, middle), &[]);
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    let findings = finding_messages(&result);
    assert!(
        findings.len() == 1 && findings[0].1.starts_with("NO_FREE_FLOOR_SPACE_FOR_CIRCLE"),
        "{findings:?}"
    );
    let evidence = result["report"]["findings"][0]["evidence"].to_string();
    assert!(evidence.contains(":bounded-not-measured="), "{evidence}");
}

/// Quarter-ring wall #29 about the origin (radii 4.8 to 5, 0 to 90
/// degrees, 3 m high) with niche #49 cut from its inner face between 40
/// and 50 degrees and z 1 to 2, the niche's inner arc one unit in the
/// last place inside the wall's. The exact boolean reads the two inner
/// faces as one surface (axiolid/kernel#324), so the wall is measured
/// (#403). `tapered` states the niche as an `IfcExtrudedAreaSolidTapered`
/// with the same end profile, an operand the exact boolean refuses, so
/// the wall is unmeasured.
fn curved_wall_with_a_flush_niche(tapered: bool) -> String {
    let arc = |first: u32,
               (outer, inner): (f64, f64),
               (from, to): (f64, f64),
               z: f64,
               depth: f64,
               tapered: bool| {
        let middle = f64::midpoint(from, to);
        let at = |r: f64, angle: f64| format!("({:?},{:?})", r * angle.cos(), r * angle.sin());
        let [list, curve, profile, origin, frame, solid] =
            [0, 1, 2, 3, 4, 5].map(|offset| first + offset);
        format!(
            "#{list}=IFCCARTESIANPOINTLIST2D(({},{},{},{},{},{}),$);\n\
             #{curve}=IFCINDEXEDPOLYCURVE(#{list},(IFCARCINDEX((1,2,3)),IFCLINEINDEX((3,4)),\
             IFCARCINDEX((4,5,6)),IFCLINEINDEX((6,1))),.F.);\n\
             #{profile}=IFCARBITRARYCLOSEDPROFILEDEF(.AREA.,$,#{curve});\n\
             #{origin}=IFCCARTESIANPOINT((0.,0.,{z:?}));\n\
             #{frame}=IFCAXIS2PLACEMENT3D(#{origin},$,$);\n\
             #{solid}={};\n",
            at(outer, from),
            at(outer, middle),
            at(outer, to),
            at(inner, to),
            at(inner, middle),
            at(inner, from),
            if tapered {
                format!("IFCEXTRUDEDAREASOLIDTAPERED(#{profile},#{frame},#4,{depth:?},#{profile})")
            } else {
                format!("IFCEXTRUDEDAREASOLID(#{profile},#{frame},#4,{depth:?})")
            },
        )
    };
    let (from, to) = (40.0_f64.to_radians(), 50.0_f64.to_radians());
    format!(
        "{}#26=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#25));\n\
         #27=IFCPRODUCTDEFINITIONSHAPE($,$,(#26));\n\
         #29=IFCWALL('0000000000000000000029',$,$,$,$,#3,#27,$,$);\n\
         {}#46=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#45));\n\
         #47=IFCPRODUCTDEFINITIONSHAPE($,$,(#46));\n\
         #49=IFCOPENINGELEMENT('0000000000000000000049',$,$,$,$,#3,#47,$,.OPENING.);\n\
         #50=IFCRELVOIDSELEMENT('0000000000000000000050',$,$,$,#29,#49);\n",
        arc(
            20,
            (5.0, 4.8),
            (0.0, std::f64::consts::FRAC_PI_2),
            0.0,
            3.0,
            false
        ),
        arc(
            40,
            (4.9, 4.8_f64.next_down()),
            (from, to),
            1.0,
            1.0,
            tapered
        ),
    )
}

/// #401: a curved wall whose opening the exact boolean refuses (here a
/// tapered niche) is unmeasured, and its box (5 m square) reached every
/// room inside the ring, leaving it not evaluated. The wall lies within
/// its uncut body, which the host measures, so that body bounds it as a
/// possible obstacle: a room inside the ring holds the circle, and a room
/// the wall's corner cuts stays not evaluated naming it, its absence
/// unproven without it.
#[test]
fn with_geometry_a_curved_wall_whose_opening_is_refused_is_bounded_by_its_uncut_body() {
    let case = Case::new("geometry-free-floor-refused-opening");
    let space = "IFCSPACE('GID',$,$,$,$,PL,REP,$,.ELEMENT.,$,$)";
    let room = |centre: f64, side: f64| {
        model_with(&format!(
            "{}{}",
            placed_box(10, [centre, centre, 0.0], [side, side, 3.0], space),
            curved_wall_with_a_flush_niche(true),
        ))
    };
    for args in [&[][..], &["--no-exact-boundaries"][..]] {
        // Inside the ring: x and y 0 to 3, its far corner 4.24 m out.
        let (output, result) = turning_circle(&case, &room(1.5, 3.0), args);
        assert_eq!(
            output.status.code(),
            Some(0),
            "{args:?} {}",
            stderr(&output)
        );
        assert_eq!(finding_messages(&result), [], "{args:?} {result:#}");
        assert_eq!(not_evaluated_messages(&result), Vec::<String>::new());
        let reasons = unmeasured_reasons(&result);
        assert!(
            reasons
                .get("#29")
                .is_some_and(|reason| reason.contains("certifies no bound")),
            "{args:?} {reasons:?}"
        );
        // x and y 2.5 to 4.5: the wall takes the far corner, so the circle
        // fits only where the wall may stand.
        let (output, result) = turning_circle(&case, &room(3.5, 2.0), args);
        assert_eq!(
            output.status.code(),
            Some(4),
            "{args:?} {}",
            stderr(&output)
        );
        let messages = not_evaluated_messages(&result);
        assert!(
            messages.len() == 1
                && messages[0].contains("bounded rather than measured")
                && messages[0].contains("/#29"),
            "{args:?} {messages:?}"
        );
    }
}

/// #403: the same wall with its niche flush on the inner face is measured
/// since the exact boolean reads the two inner faces as one surface
/// (axiolid/kernel#324), so neither room is left undecided by it: the room
/// inside the ring holds the circle, and the room the wall's corner cuts
/// is decided by the wall's measured body.
#[test]
fn with_geometry_a_curved_wall_with_a_flush_niche_is_measured() {
    let case = Case::new("geometry-free-floor-flush-niche");
    let space = "IFCSPACE('GID',$,$,$,$,PL,REP,$,.ELEMENT.,$,$)";
    let room = |centre: f64, side: f64| {
        model_with(&format!(
            "{}{}",
            placed_box(10, [centre, centre, 0.0], [side, side, 3.0], space),
            curved_wall_with_a_flush_niche(false),
        ))
    };
    for args in [&[][..], &["--no-exact-boundaries"][..]] {
        // Inside the ring, and x and y 2.5 to 4.5, where the wall crosses
        // the room and leaves no 1.5 m circle: the largest lies beyond it.
        for (centre, side, code) in [(1.5, 3.0, 0), (3.5, 2.0, 3)] {
            let (output, result) = turning_circle(&case, &room(centre, side), args);
            assert_eq!(
                output.status.code(),
                Some(code),
                "{args:?} {centre}: {}",
                stderr(&output)
            );
            let reasons = unmeasured_reasons(&result);
            assert!(reasons.is_empty(), "{args:?} {centre}: {reasons:?}");
            assert_eq!(
                not_evaluated_messages(&result),
                Vec::<String>::new(),
                "{args:?} {centre}: {result:#}"
            );
            let findings = finding_messages(&result);
            assert!(
                if code == 0 {
                    findings.is_empty()
                } else {
                    findings.len() == 1
                        && findings[0].1.starts_with("NO_FREE_FLOOR_SPACE_FOR_CIRCLE")
                },
                "{args:?} {centre}: {findings:?}"
            );
        }
    }
}

/// The largest free circle's bracket and centre, read from the evidence a
/// failed free-floor finding cites (#391).
fn largest(finding: &Value) -> (f64, f64, Vec<f64>) {
    let locator = finding["evidence"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|evidence| evidence["locator"].as_str())
        .find(|locator| locator.contains(":largest="))
        .unwrap_or_else(|| panic!("no largest circle in {finding:#}"));
    let numbers = |text: &str| -> Vec<f64> {
        text.trim_matches(|c| c == '[' || c == ']')
            .split(',')
            .map(|number| number.parse().unwrap())
            .collect()
    };
    let rest = locator.split(":largest=").nth(1).unwrap();
    let (bracket, centre) = rest.split_once(":centre=").unwrap();
    let bracket = numbers(bracket);
    (bracket[0], bracket[1], numbers(centre))
}

/// Room #19 (x 0..2.4, y 0..1.6, 3 m high) with door #50 in its north
/// wall: hinged at (1.2, 1.7), its 0.9 m leaf closed westward and opening
