/// engine#404: a body clipped by an `IfcPolygonalBoundedHalfSpace` whose
/// prism is oblique to its plane is measured at its clipped volume, where
/// ifc-geometry 0.27.1 refused it and 0.27.2 compiled convex boundaries
/// only, without an exact body to certify against. Since ifc-geometry 0.28
/// every such clip lowers to one bounded half-space along `Position`'s Z,
/// which both kernel compilers build (openbimrs/ifc#515,
/// axiolid/kernel#321): the gable wall at 49.999912042537 m³, and
/// [`wall_clipped_within_a_boundary`]'s wall with its clipping plane
/// sloped to `z = 2 - 0.3 x` under a rectangular, an L-shaped
/// (non-convex) and an arc boundary.
#[test]
fn with_geometry_a_wall_clipped_by_an_oblique_bounded_half_space_is_measured() {
    let volume = json!({"kind": "property", "propertySet": "axioval:measured",
                        "property": "volume"});
    let cubic = |value: f64| json!({"kind": "literal", "value": {"type": "quantity", "value": value, "unit": "m3"}});
    let within = |expected: f64| {
        json!({"requirement": {"type": "expression", "value":
            {"kind": "between", "operand": volume,
             "low": cubic(expected - 1e-6), "high": cubic(expected + 1e-6)}}})
    };
    let sloped = |boundary: &str| {
        wall_clipped_within_a_boundary(boundary).replace(
            "#22=IFCAXIS2PLACEMENT3D(#21,$,$);\n",
            "#22=IFCAXIS2PLACEMENT3D(#21,#32,$);\n#32=IFCDIRECTION((0.3,0.,1.));\n",
        )
    };
    let rectangle = "#15=IFCCARTESIANPOINT((0.,-1.));\n\
         #16=IFCCARTESIANPOINT((3.,-1.));\n\
         #17=IFCCARTESIANPOINT((3.,1.));\n\
         #18=IFCCARTESIANPOINT((0.,1.));\n\
         #20=IFCPOLYLINE((#15,#16,#17,#18,#15));\n";
    // An L: x 1 to 2 across the wall, x 0 to 1 over its y < 0 half only.
    let l_shaped = "#15=IFCCARTESIANPOINTLIST2D(((0.,-1.),(3.,-1.),(3.,1.),(1.,1.),(1.,0.),(0.,0.)));\n\
         #20=IFCINDEXEDPOLYCURVE(#15,(IFCLINEINDEX((1,2,3,4,5,6,1))),$);\n";
    let arc = "#15=IFCCARTESIANPOINTLIST2D(((0.,-1.),(3.,-1.),(3.5,0.),(3.,1.),(0.,1.)));\n\
         #20=IFCINDEXEDPOLYCURVE(#15,(IFCLINEINDEX((1,2)),IFCARCINDEX((2,3,4)),IFCLINEINDEX((4,5,1))),$);\n";
    // The uncut wall is 3.6 m³. Above the sloped plane, x 0 to 2 loses
    // 0.3 m x 2.6 m² = 0.78 m³; under the L, x 0 to 1 loses
    // 0.15 m x 1.15 m² and x 1 to 2 loses 0.3 m x 1.45 m².
    for (name, model, expected) in [
        ("gable", GABLE_WALL.to_owned(), 49.999_912_042_537),
        ("rectangle", sloped(rectangle), 2.82),
        ("l-shaped", sloped(l_shaped), 3.6 - 0.15 * 1.15 - 0.3 * 1.45),
        ("arc", sloped(arc), 2.82),
    ] {
        let case = Case::new(&format!("geometry-oblique-clip-{name}"));
        let (output, result) = case.geometry_rule(
            &model,
            &[("wall", "IfcWall")],
            "axioval:capability.expression",
            &registry_signature("axioval:capability.expression"),
            entity("wall"),
            within(expected),
        );
        assert_eq!(output.status.code(), Some(0), "{name}: {result:#}");
        assert_eq!(result["report"]["findings"], json!([]), "{name}");
        assert_eq!(
            result["report"]["not_evaluated"],
            json!([]),
            "{name}: {result:#}"
        );
        assert!(
            result["geometry"]["unmeasured"]
                .as_array()
                .is_none_or(Vec::is_empty),
            "{name}: {result:#}"
        );
        // Planar clips are meshed exactly; the arc's cylinder wall is
        // tessellated within the deviation certified against the exact
        // body.
        assert_eq!(
            result["geometry"]["tessellated"],
            u64::from(name == "arc"),
            "{name}: {result:#}"
        );
    }
}

/// A disk swept along a polyline with a sharp corner and no fillet radius
/// is mitred at half angle, as `IfcSweptDiskSolid` defines it, and the
/// kernel proves its mesh within the chord budget again
/// (axiolid/kernel#245): the body is measured and declared within the
/// certified 1 mm, like the same polyline with a fillet radius
/// (`IfcSweptDiskSolidPolygonal`). A closed polyline sweeps as a loop
/// since axiolid-mesh-compile 0.3.24 (axiolid/kernel#248) and is measured
/// too. Still refused by name, and so unmeasured with the reason and its
/// clashes not evaluated: a fillet radius equal to the disk radius, whose
/// bend is a horn torus.
#[test]
fn a_swept_disk_round_an_unfilleted_corner_is_certified() {
    let case = Case::new("unfilleted-corner");
    let bent = |id: u32, x: f64, closed: bool, solid: &str| {
        format!(
            "#{a}=IFCCARTESIANPOINT(({x0:.1},0.,1.));\n\
             #{b}=IFCCARTESIANPOINT(({x1:.1},0.,1.));\n\
             #{c}=IFCCARTESIANPOINT(({x1:.1},2.,1.));\n\
             #{line}=IFCPOLYLINE((#{a},#{b},#{c}{close}));\n\
             #{disk}={solid};\n\
             #{shape}=IFCSHAPEREPRESENTATION(#5,'Body','AdvancedSweptSolid',(#{disk}));\n\
             #{definition}=IFCPRODUCTDEFINITIONSHAPE($,$,(#{shape}));\n\
             #{id}=IFCWALL('{id:022}',$,$,$,$,#3,#{definition},$,$);\n",
            a = id - 7,
            b = id - 6,
            c = id - 5,
            line = id - 4,
            disk = id - 3,
            shape = id - 2,
            definition = id - 1,
            x0 = x,
            x1 = x + 2.0,
            close = if closed {
                format!(",#{}", id - 7)
            } else {
                String::new()
            },
            solid = solid.replace("LINE", &format!("#{}", id - 4)),
        )
    };
    let model = crossing_walls_with(&format!(
        "{}{}{}{}",
        bent(68, 10.0, false, "IFCSWEPTDISKSOLID(LINE,0.05,$,$,$)"),
        bent(
            78,
            14.0,
            false,
            "IFCSWEPTDISKSOLIDPOLYGONAL(LINE,0.05,$,$,$,0.2)"
        ),
        bent(88, 18.0, true, "IFCSWEPTDISKSOLID(LINE,0.05,$,$,$)"),
        bent(
            98,
            22.0,
            false,
            "IFCSWEPTDISKSOLIDPOLYGONAL(LINE,0.05,$,$,$,0.05)"
        ),
    ));
    let (output, result) = case.wall_clash(&model, &json!({}));
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    let unmeasured = result["geometry"]["unmeasured"].as_array().unwrap();
    let reason = |local: &str| {
        unmeasured
            .iter()
            .find(|entry| entry["object"]["local_id"] == local)
            .and_then(|entry| entry["reason"].as_str())
            .map(str::to_owned)
    };
    // The sharp corner and the filleted one are both measured, each mesh
    // declared within the certified chord tolerance.
    assert_eq!(reason("#68"), None, "{result:#}");
    assert_eq!(reason("#78"), None, "{result:#}");
    // Since axiolid-mesh-compile 0.3.24 (axiolid/kernel#248) a closed
    // polyline sweeps as a loop, so the closed ring is measured too.
    assert_eq!(reason("#88"), None, "{result:#}");
    assert_eq!(result["geometry"]["tessellated"], 3, "{result:#}");
    let horn = reason("#98").unwrap_or_else(|| panic!("{result:#}"));
    assert!(
        horn.contains("equals the fillet radius") && horn.contains("horn torus"),
        "{horn}"
    );
    let not_evaluated = result["report"]["not_evaluated"].to_string();
    assert!(
        !not_evaluated.contains("#68")
            && !not_evaluated.contains("#78")
            && !not_evaluated.contains("#88"),
        "{result:#}"
    );
    assert!(not_evaluated.contains("#98"), "{result:#}");
}

/// A wall #69 as an `IfcFacetedBrep`, the unit box at x 10 with its
/// corner (11, 1, 1) lifted 5 cm, so its top face is a
/// warped quad (the side faces keep their corners in their planes;
/// axiolid/kernel#254). The mesh compiler reports a faceted
/// face without a surface by the slab width of its corners (#257, #261),
/// and the bridge declares the mesh within it: the wall is measured as
/// tessellated, never exact, and never unmeasured.
#[test]
fn a_faceted_body_with_a_warped_face_is_tessellated() {
    let case = Case::new("warped-faceted-face");
    let corners = [
        [10.0, 0.0, 0.0],
        [11.0, 0.0, 0.0],
        [11.0, 1.0, 0.0],
        [10.0, 1.0, 0.0],
        [10.0, 0.0, 1.0],
        [11.0, 0.0, 1.0],
        [11.0, 1.0, 1.05],
        [10.0, 1.0, 1.0],
    ];
    // Outward: bottom, top, front, right, back, left.
    let faces: [[usize; 4]; 6] = [
        [0, 3, 2, 1],
        [4, 5, 6, 7],
        [0, 1, 5, 4],
        [1, 2, 6, 5],
        [2, 3, 7, 6],
        [3, 0, 4, 7],
    ];
    let mut data = String::new();
    for (index, [x, y, z]) in corners.iter().enumerate() {
        writeln!(
            data,
            "#{}=IFCCARTESIANPOINT(({x:?},{y:?},{z:?}));",
            100 + index
        )
        .unwrap();
    }
    let mut face_ids = Vec::new();
    for (index, face) in faces.iter().enumerate() {
        let [poly, bound, id] = [0, 1, 2].map(|offset| 110 + 3 * index + offset);
        let points: Vec<String> = face.iter().map(|c| format!("#{}", 100 + c)).collect();
        writeln!(
            data,
            "#{poly}=IFCPOLYLOOP(({}));\n#{bound}=IFCFACEOUTERBOUND(#{poly},.T.);\n\
             #{id}=IFCFACE((#{bound}));",
            points.join(",")
        )
        .unwrap();
        face_ids.push(format!("#{id}"));
    }
    writeln!(
        data,
        "#140=IFCCLOSEDSHELL(({}));\n#141=IFCFACETEDBREP(#140);\n\
         #142=IFCSHAPEREPRESENTATION(#5,'Body','Brep',(#141));\n\
         #143=IFCPRODUCTDEFINITIONSHAPE($,$,(#142));\n\
         #69=IFCWALL('0000000000000000000069',$,$,$,$,#3,#143,$,$);",
        face_ids.join(",")
    )
    .unwrap();
    let (output, result) = case.wall_clash(&crossing_walls_with(&data), &json!({}));
    // The crossing walls still clash; the warped wall stands apart.
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    let geometry = &result["geometry"];
    assert!(
        !geometry["unmeasured"].to_string().contains("#69"),
        "{geometry:#}"
    );
    assert_eq!(geometry["tessellated"], 1, "{geometry:#}");
    assert!(
        !result["report"]["not_evaluated"]
            .to_string()
            .contains("#69"),
        "{result:#}"
    );
}

/// A ring 5 km round needs more than the kernel's 4096 steps a turn to stay
/// within the 1 mm chord tolerance (axiolid/kernel#231): the kernel refuses
/// the budget rather than mesh it coarser, so the wall is unmeasured with
/// the reason and the clash between the other walls is still found.
#[test]
fn a_body_beyond_the_kernels_step_budget_is_unmeasured() {
    let case = Case::new("step-budget");
    let ring = "#40=IFCCARTESIANPOINT((5000.,0.));\n\
                #41=IFCAXIS2PLACEMENT2D(#40,$);\n\
                #42=IFCRECTANGLEPROFILEDEF(.AREA.,$,#41,0.2,0.2);\n\
                #43=IFCDIRECTION((0.,1.,0.));\n\
                #44=IFCAXIS1PLACEMENT(#1,#43);\n\
                #45=IFCREVOLVEDAREASOLID(#42,#2,#44,6.283185307179586);\n\
                #46=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#45));\n\
                #47=IFCPRODUCTDEFINITIONSHAPE($,$,(#46));\n\
                #48=IFCWALL('0000000000000000000048',$,$,$,$,#3,#47,$,$);\n";
    let (output, result) = case.wall_clash(&crossing_walls_with(ring), &json!({}));
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    let findings = result["report"]["findings"].as_array().unwrap();
    assert_eq!(findings.len(), 1, "{result:#}");
    let unmeasured = result["geometry"]["unmeasured"].as_array().unwrap();
    let ring = unmeasured
        .iter()
        .find(|entry| entry["object"]["local_id"] == "#48")
        .unwrap_or_else(|| panic!("{result:#}"));
    let reason = ring["reason"].as_str().unwrap();
    assert!(
        reason.contains("within the 0.001 m chord tolerance")
            && reason.contains("revolution angular steps")
            && reason.contains("a coarser mesh would break that tolerance"),
        "{reason}"
    );
    // Its clashes are neither found nor passed.
    assert!(
        result["report"]["not_evaluated"]
            .as_array()
            .unwrap()
            .iter()
            .any(|outcome| outcome.to_string().contains("#48")),
        "{result:#}"
    );
}

/// The packages of the not-evaluated inventory (`scripts/inventory`) bind
/// every capability with its current signature, so they keep compiling, and
/// run with geometry: the proxy without a body is unmeasured, so the clash
/// and triangle-count rules are not evaluated for it rather than passed.
#[test]
fn the_not_evaluated_inventory_packages_bind_and_run_with_geometry() {
    let inventory = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../scripts/inventory");
    let definitions = format!("{inventory}/definitions.json");
    let ruleset = format!("{inventory}/ruleset.json");
    let declared: Value =
        serde_json::from_str(&std::fs::read_to_string(&definitions).unwrap()).unwrap();
    for (id, definition) in declared["definitions"].as_object().unwrap() {
        let capability = definition["capability"].as_str().unwrap();
        assert_eq!(
            definition["parameters"],
            registry_signature(capability),
            "{id}: regenerate its signature from the registry"
        );
    }

    let case = Case::new("not-evaluated-inventory");
    let model = case.write("model.ifc", &crossing_walls());
    let saved = case.path("result.json");
    let output = Command::new(env!("CARGO_BIN_EXE_axioval"))
        .args(["check", "--geometry", "--model"])
        .arg(&model)
        .args([
            "--definitions",
            &definitions,
            "--ruleset",
            &ruleset,
            "--report",
        ])
        .arg(&saved)
        .output()
        .unwrap();
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    let result: Value = serde_json::from_str(&std::fs::read_to_string(&saved).unwrap()).unwrap();
    assert_eq!(
        result["geometry"]["unmeasured"][0]["object"]["local_id"],
        "#30"
    );
    let refused: Vec<&str> = result["report"]["not_evaluated"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|outcome| outcome["object_id"]["local_id"] == "#30")
        .map(|outcome| outcome["rule_id"].as_str().unwrap())
        .collect();
    assert_eq!(
        refused,
        ["element-clash", "element-triangle-count"],
        "{result:#}"
    );
}

/// Spaces #16 (x 0..4) and #26 (x 20..24), 3 m high, and slab #36, whose
/// only representation is a `Box` (with `bound`) or nothing: it has no body,
/// so it is unmeasured. Its box lies over the first space's ceiling. With
/// `roof`, roof #50 has no body and is made of slab #36, so it is
/// unmeasured through its part and bounded by the part's box.
fn spaces_beside_an_unmeasured_slab(bound: bool, roof: bool) -> String {
    let space = |first: u32, x: f64| {
        body(
            first,
            x,
            4.0,
            3.0,
            &format!(
                "IFCSPACE('00000000000000000000{:02}',$,$,$,$,#3,REP,$,.ELEMENT.,$,$)",
                first + 6
            ),
        )
    };
    let slab = if bound {
        "#30=IFCCARTESIANPOINT((0.,0.,3.));\n\
         #31=IFCBOUNDINGBOX(#30,4.,4.,0.2);\n\
         #32=IFCSHAPEREPRESENTATION(#5,'Box','BoundingBox',(#31));\n\
         #33=IFCPRODUCTDEFINITIONSHAPE($,$,(#32));\n\
         #36=IFCSLAB('0000000000000000000036',$,$,$,$,#3,#33,$,.FLOOR.);\n"
    } else {
        "#36=IFCSLAB('0000000000000000000036',$,$,$,$,#3,$,$,.FLOOR.);\n"
    };
    let roof = if roof {
        "#50=IFCROOF('0000000000000000000050',$,$,$,$,#3,$,$,.NOTDEFINED.);\n\
         #51=IFCRELAGGREGATES('0000000000000000000051',$,$,$,#50,(#36));\n"
    } else {
        ""
    };
    format!(
        "ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION((''),'2;1');\nFILE_NAME('n','t',(''),(''),'p','o','a');\nFILE_SCHEMA(('IFC4'));\nENDSEC;\nDATA;\n\
         #1=IFCCARTESIANPOINT((0.,0.,0.));\n\
         #2=IFCAXIS2PLACEMENT3D(#1,$,$);\n\
         #3=IFCLOCALPLACEMENT($,#2);\n\
         #4=IFCDIRECTION((0.,0.,1.));\n\
         #5=IFCGEOMETRICREPRESENTATIONCONTEXT($,'Model',3,1.E-05,#2,$);\n\
         {}{}{slab}{roof}\
         ENDSEC;\nEND-ISO-10303-21;\n",
        space(10, 2.0),
        space(20, 22.0),
    )
}

/// The spaces of [`spaces_beside_an_unmeasured_slab`] with slab #36 given
/// a body, 4 x 4 x 0.2 m over the first space's ceiling, and an opening
/// #45 through it: an ellipse extruded obliquely, which the kernel's exact
/// boolean refuses, so the slab's net body is unmeasured while its gross
/// body is measured. (An oblique rounded square served until the kernel
/// cut those walls, axiolid/kernel#287, #317.)
fn spaces_beside_a_slab_unmeasured_through_its_opening() -> String {
    spaces_beside_an_unmeasured_slab(false, false).replace(
        "#36=IFCSLAB('0000000000000000000036',$,$,$,$,#3,$,$,.FLOOR.);\n",
        "#30=IFCCARTESIANPOINT((2.,2.));\n\
         #31=IFCAXIS2PLACEMENT2D(#30,$);\n\
         #32=IFCRECTANGLEPROFILEDEF(.AREA.,$,#31,4.,4.);\n\
         #33=IFCCARTESIANPOINT((0.,0.,3.));\n\
         #34=IFCAXIS2PLACEMENT3D(#33,$,$);\n\
         #35=IFCEXTRUDEDAREASOLID(#32,#34,#4,0.2);\n\
         #37=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#35));\n\
         #38=IFCPRODUCTDEFINITIONSHAPE($,$,(#37));\n\
         #36=IFCSLAB('0000000000000000000036',$,$,$,$,#3,#38,$,.FLOOR.);\n\
         #39=IFCELLIPSEPROFILEDEF(.AREA.,$,#31,0.5,0.4);\n\
         #40=IFCCARTESIANPOINT((0.,0.,2.9));\n\
         #41=IFCAXIS2PLACEMENT3D(#40,$,$);\n\
         #42=IFCDIRECTION((0.1,0.,1.));\n\
         #43=IFCEXTRUDEDAREASOLID(#39,#41,#42,0.4);\n\
         #44=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#43));\n\
         #46=IFCPRODUCTDEFINITIONSHAPE($,$,(#44));\n\
         #45=IFCOPENINGELEMENT('0000000000000000000045',$,$,$,$,#3,#46,$,.OPENING.);\n\
         #47=IFCRELVOIDSELEMENT('0000000000000000000047',$,$,$,#36,#45);\n",
    )
}

/// An unmeasured slab refuses only the space measurements it could change
/// (#212): with the box the file states, the far space is judged and the
/// space under the box keeps only its top cap, overlaps and boundary gaps
/// not evaluated; without one it may be anywhere and refuses them for both.
/// Every refusal names the slab. A roof made of the slab is unmeasured
/// through it and bounded by its box, so it blocks only where the slab does.
/// A slab with a body, unmeasured once its opening is subtracted, is
/// bounded by its gross body, which its net body lies inside, so it blocks
/// only where the boxed slab does too (#301).
#[test]
fn with_geometry_an_unmeasured_slab_refuses_only_the_spaces_it_reaches() {
    let inventory = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../scripts/inventory");
    let definitions = format!("{inventory}/definitions.json");
    let ruleset = format!("{inventory}/ruleset.json");
    let refused = |bound: bool, roof: bool| {
        let case = Case::new(&format!("space-unmeasured-slab-{bound}-{roof}"));
        let model = case.write("model.ifc", &spaces_beside_an_unmeasured_slab(bound, roof));
        refused_spaces(&case, &model, &definitions, &ruleset, roof)
    };
    let near = |local: &str| {
        [
            "space boundary gaps",
            "space overlaps",
            "space top cap coverage",
        ]
        .map(|aspect| (local.to_owned(), aspect.to_owned()))
    };
    assert_eq!(refused(true, false), near("#16"));
    assert_eq!(refused(true, true), near("#16"));
    // Without a box the slab may be anywhere, the floors included.
    let anywhere = |local: &str| {
        let mut aspects = vec![(local.to_owned(), "space bottom cap coverage".to_owned())];
        aspects.extend(near(local));
        aspects
    };
    let mut everywhere = anywhere("#16");
    everywhere.extend(anywhere("#26"));
    assert_eq!(refused(false, false), everywhere);

    let case = Case::new("space-unmeasured-slab-gross");
    let model = case.write(
        "model.ifc",
        &spaces_beside_a_slab_unmeasured_through_its_opening(),
    );
    assert_eq!(
        refused_spaces(&case, &model, &definitions, &ruleset, false),
        near("#16")
    );
}

/// The space-validation outcomes refused over `model` checked with the
/// inventory's packages, as (space, aspect), each naming slab #36 (and
/// roof #50 exactly when `roof`).
fn refused_spaces(
    case: &Case,
    model: &Path,
    definitions: &str,
    ruleset: &str,
    roof: bool,
) -> Vec<(String, String)> {
    {
        let saved = case.path("result.json");
        let output = Command::new(env!("CARGO_BIN_EXE_axioval"))
            .args(["check", "--geometry", "--model"])
            .arg(model)
            .args([
                "--definitions",
                definitions,
                "--ruleset",
                ruleset,
                "--report",
            ])
            .arg(&saved)
            .output()
            .unwrap();
        assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
        let result: Value =
            serde_json::from_str(&std::fs::read_to_string(&saved).unwrap()).unwrap();
        let mut refused: Vec<(String, String)> = result["report"]["not_evaluated"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|outcome| outcome["rule_id"] == "space-validation")
            .map(|outcome| {
                let message = outcome["message"].as_str().unwrap();
                assert!(message.contains("/#36"), "{message}");
                assert_eq!(message.contains("/#50"), roof, "{message}");
                (
                    outcome["object_id"]["local_id"]
                        .as_str()
                        .unwrap()
                        .to_owned(),
                    message.split(" is unavailable").next().unwrap().to_owned(),
                )
            })
            .collect();
        refused.sort();
        refused
    }
}

/// Spaces #16 (x 0..4), #26 (x 20..24), #46 (x 40..44) and #96 (x
/// 60..64), each 4 x 4 m and 3 m high, beside three unmeasured obstacles
/// (#357, #358):
///
/// - wall #66 in #16 (x 1..2, y 1..2, 3 m high), its extrusion clipped by a
///   polygonal bounded half-space whose boundary has a point off its plane,
///   which `ifc-geometry` refuses as geometrically invalid. A clip only
///   removes material, so the extrusion bounds it;
/// - railing #80 in #26, with no body of its own, made of member #78, one
///   vertical face (x 21..22, y 2, z 0..1) whose boundary crosses itself
///   (its first and third edges cross), which the mesh compiler refuses.
///   Its authored corners bound the member, and the member bounds the
///   railing;
/// - proxy #106 in #46, a vertical 1 x 1 m square (x 41..42, y 2, z 1..2)
///   extruded 1 m along x, in its own plane, which the kernel refuses by
///   name. The square swept along that segment bounds it.
///
/// `extra` is written into the data section after them.
fn spaces_beside_unmeasured_obstacles(extra: &str) -> String {
    let space = |first: u32, x: f64| {
        body(
            first,
            x,
            4.0,
            3.0,
            &format!(
                "IFCSPACE('00000000000000000000{:02}',$,$,$,$,#3,REP,$,.ELEMENT.,$,$)",
                first + 6
            ),
        )
    };
    format!(
        "ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION((''),'2;1');\nFILE_NAME('n','t',(''),(''),'p','o','a');\nFILE_SCHEMA(('IFC4'));\nENDSEC;\nDATA;\n\
         #1=IFCCARTESIANPOINT((0.,0.,0.));\n\
         #2=IFCAXIS2PLACEMENT3D(#1,$,$);\n\
         #3=IFCLOCALPLACEMENT($,#2);\n\
         #4=IFCDIRECTION((0.,0.,1.));\n\
         #5=IFCGEOMETRICREPRESENTATIONCONTEXT($,'Model',3,1.E-05,#2,$);\n\
         {}{}{}{}\
         #50=IFCCARTESIANPOINT((1.5,1.5));\n\
         #51=IFCAXIS2PLACEMENT2D(#50,$);\n\
         #52=IFCRECTANGLEPROFILEDEF(.AREA.,$,#51,1.,1.);\n\
         #53=IFCEXTRUDEDAREASOLID(#52,#2,#4,3.);\n\
         #54=IFCCARTESIANPOINT((0.,0.,2.));\n\
         #55=IFCAXIS2PLACEMENT3D(#54,$,$);\n\
         #56=IFCPLANE(#55);\n\
         #57=IFCCARTESIANPOINT((0.,0.,0.));\n\
         #58=IFCCARTESIANPOINT((3.,0.,0.));\n\
         #59=IFCCARTESIANPOINT((3.,3.,0.25));\n\
         #60=IFCCARTESIANPOINT((0.,3.,0.));\n\
         #61=IFCPOLYLINE((#57,#58,#59,#60,#57));\n\
         #62=IFCPOLYGONALBOUNDEDHALFSPACE(#56,.F.,#55,#61);\n\
         #63=IFCBOOLEANCLIPPINGRESULT(.DIFFERENCE.,#53,#62);\n\
         #64=IFCSHAPEREPRESENTATION(#5,'Body','Clipping',(#63));\n\
         #65=IFCPRODUCTDEFINITIONSHAPE($,$,(#64));\n\
         #66=IFCWALL('0000000000000000000066',$,$,$,$,#3,#65,$,$);\n\
         #70=IFCCARTESIANPOINTLIST3D(((21.,2.,0.),(22.,2.,1.),(22.,2.,0.),(21.,2.,0.5)),$);\n\
         #71=IFCINDEXEDPOLYGONALFACE((1,2,3,4));\n\
         #72=IFCPOLYGONALFACESET(#70,.F.,(#71),$);\n\
         #73=IFCSHAPEREPRESENTATION(#5,'Body','Tessellation',(#72));\n\
         #74=IFCPRODUCTDEFINITIONSHAPE($,$,(#73));\n\
         #78=IFCMEMBER('0000000000000000000078',$,$,$,$,#3,#74,$,.MEMBER.);\n\
         #80=IFCRAILING('0000000000000000000080',$,$,$,$,#3,$,$,.HANDRAIL.);\n\
         #81=IFCRELAGGREGATES('0000000000000000000081',$,$,$,#80,(#78));\n\
         #100=IFCCARTESIANPOINT((41.5,1.5));\n\
         #101=IFCAXIS2PLACEMENT2D(#100,$);\n\
         #102=IFCRECTANGLEPROFILEDEF(.AREA.,$,#101,1.,1.);\n\
         #103=IFCDIRECTION((1.,0.,0.));\n\
         #108=IFCCARTESIANPOINT((0.,2.,0.));\n\
         #109=IFCDIRECTION((0.,-1.,0.));\n\
         #110=IFCAXIS2PLACEMENT3D(#108,#109,#103);\n\
         #104=IFCEXTRUDEDAREASOLID(#102,#110,#103,1.);\n\
         #105=IFCSHAPEREPRESENTATION(#5,'Body','SweptSolid',(#104));\n\
         #107=IFCPRODUCTDEFINITIONSHAPE($,$,(#105));\n\
         #106=IFCBUILDINGELEMENTPROXY('0000000000000000000106',$,$,$,$,#3,#107,$,$);\n\
         {extra}\
         ENDSEC;\nEND-ISO-10303-21;\n",
        space(10, 2.0),
        space(20, 22.0),
        space(40, 42.0),
        space(90, 62.0),
    )
}

/// Invalid IFC geometry, and a whole unmeasured only through a part's model
/// data, are model data (#357): wall #66 is reported once as the integrity
/// warning `shape.invalid-geometry`, and railing #80 with its member's code,
/// `shape.self-intersecting-face`, beside the member's own.
///
/// They stay unmeasured but are bounded soundly (#358): the wall by its
/// clipped extrusion, the member by its authored corners, the railing by
/// its member, and the proxy extruded in its profile's plane by its
/// profile swept along the extrusion. So each refuses the free floor of
/// the space it stands in and only that one, and the space apart from all
/// of them decides.
#[test]
#[allow(clippy::too_many_lines)]
fn with_geometry_unmeasured_obstacles_bounded_apart_leave_a_floor_search_decided() {
    let inventory = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../scripts/inventory");
    let case = Case::new("space-unmeasured-obstacles");
    let model = case.write("model.ifc", &spaces_beside_unmeasured_obstacles(""));
    let saved = case.path("result.json");
    let output = Command::new(env!("CARGO_BIN_EXE_axioval"))
        .args(["check", "--geometry", "--model"])
        .arg(&model)
        .args([
            "--definitions",
            &format!("{inventory}/definitions.json"),
            "--ruleset",
            &format!("{inventory}/ruleset.json"),
            "--report",
        ])
        .arg(&saved)
        .output()
        .unwrap();
    assert!(
        matches!(output.status.code(), Some(3 | 4)),
        "{}",
        stderr(&output)
    );
    let result: Value = serde_json::from_str(&std::fs::read_to_string(&saved).unwrap()).unwrap();

    let reason = |local: &str| {
        result["geometry"]["unmeasured"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["object"]["local_id"] == local)
            .and_then(|entry| entry["reason"].as_str())
            .unwrap_or_else(|| panic!("{local} is measured: {:#}", result["geometry"]))
            .to_owned()
    };
    assert!(
        reason("#66").starts_with("#59 (IFCCARTESIANPOINT) is geometrically invalid: "),
        "{}",
        reason("#66")
    );
    assert!(
        reason("#78").ends_with("profile outer ring intersects itself"),
        "{}",
        reason("#78")
    );
    assert!(
        reason("#80").starts_with(
            "no body representation of its own, and its body is the union of its 1 part, \
             and part ifc-step:model.ifc/#78 is unmeasured: "
        ),
        "{}",
        reason("#80")
    );

    let notes: Vec<(&str, &str, &str)> = result["integrity"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|record| record["severity"] == "warning")
        .filter_map(|record| {
            let locator = record["locator"].as_str()?;
            Some((
                record["code"].as_str()?,
                locator.rsplit_once(':')?.1,
                record["message"].as_str()?,
            ))
        })
        .filter(|(code, _, _)| code.starts_with("shape."))
        .collect();
    assert_eq!(
        notes
            .iter()
            .map(|(code, local, _)| (*code, *local))
            .collect::<Vec<_>>(),
        [
            ("shape.invalid-geometry", "#66"),
            ("shape.self-intersecting-face", "#78"),
            ("shape.self-intersecting-face", "#80"),
        ],
        "{:#}",
        result["integrity"]
    );
    assert!(
        notes[0].2.starts_with(
            "#66 IFCWALL has geometry that cannot exist as written (#59 (IFCCARTESIANPOINT) is \
             geometrically invalid: "
        ),
        "{}",
        notes[0].2
    );
    assert_eq!(
        notes[2].2,
        "#80 IFCRAILING has no body of its own, and its part #78 IFCMEMBER is unmeasured for \
         its model data (shape.self-intersecting-face); every measurement of it is not \
         evaluated"
    );
    let locators = result["integrity"].to_string();
    assert!(locators.contains(":invalid-geometry:#66\""), "{locators}");
    assert!(
        locators.contains(":self-intersecting-face:#80\""),
        "{locators}"
    );

    // Each space's free floor: refused by the obstacle it holds alone,
    // decided where none stands.
    let floors: BTreeMap<String, String> = ["#16", "#26", "#46", "#96"]
        .into_iter()
        .map(|space| {
            let refusal = result["report"]["not_evaluated"]
                .as_array()
                .unwrap()
                .iter()
                .find(|outcome| {
                    outcome["rule_id"] == "space-free-floor"
                        && outcome["object_id"]["local_id"] == space
                })
                .map_or_else(
                    || "decided".to_owned(),
                    |outcome| {
                        let message = outcome["message"].as_str().unwrap();
                        ["#66", "#78", "#80", "#106"]
                            .into_iter()
                            .filter(|obstacle| message.contains(&format!("/{obstacle}")))
                            .collect::<Vec<_>>()
                            .join(" ")
                    },
                );
            (space.to_owned(), refusal)
        })
        .collect();
    assert_eq!(
        floors,
        BTreeMap::from([
            ("#16".to_owned(), "#66".to_owned()),
            ("#26".to_owned(), "#78".to_owned()),
            ("#46".to_owned(), "#106".to_owned()),
            ("#96".to_owned(), "decided".to_owned()),
        ]),
        "{:#}",
        result["report"]["not_evaluated"]
    );
}

/// An unmeasured whole lies within the union of its parts' bounds, and an
/// unmeasured body within the union of its items' bounds, not the box
/// around them (#358). Beside the obstacles of
/// `spaces_beside_unmeasured_obstacles`, both stand either side of space
/// #96 (x 60..64), whose free floor still decides:
///
/// - railing #140 of member #149 (measured, x 58..59) and member #142 (a
///   vertical face at x 65..66 whose boundary crosses itself);
/// - proxy #150 of two face sets whose boundaries cross themselves, at
///   x 58.2..58.8 and x 65.2..65.8.
///
/// The box around either reaches over #96 and would refuse it.
#[test]
fn with_geometry_unmeasured_obstacles_either_side_of_a_space_leave_its_floor_search_decided() {
    let inventory = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../scripts/inventory");
    let case = Case::new("space-unmeasured-either-side");
    let crossed = |list: u32, x: f64, y: f64, width: f64| {
        let (a, b) = (x, x + width);
        format!(
            "#{list}=IFCCARTESIANPOINTLIST3D((({a:?},{y:?},0.),({b:?},{y:?},1.),({b:?},{y:?},0.),\
             ({a:?},{y:?},0.5)),$);\n\
             #{face}=IFCINDEXEDPOLYGONALFACE((1,2,3,4));\n\
             #{set}=IFCPOLYGONALFACESET(#{list},.F.,(#{face}),$);\n",
            face = list + 1,
            set = list + 2,
        )
    };
    let extra = format!(
        "{}{}\
         #163=IFCSHAPEREPRESENTATION(#5,'Body','Tessellation',(#162));\n\
         #164=IFCPRODUCTDEFINITIONSHAPE($,$,(#163));\n\
         #142=IFCMEMBER('0000000000000000000142',$,$,$,$,#3,#164,$,.MEMBER.);\n\
         #140=IFCRAILING('0000000000000000000140',$,$,$,$,#3,$,$,.HANDRAIL.);\n\
         #141=IFCRELAGGREGATES('0000000000000000000141',$,$,$,#140,(#149,#142));\n\
         {}{}\
         #176=IFCSHAPEREPRESENTATION(#5,'Body','Tessellation',(#172,#175));\n\
         #177=IFCPRODUCTDEFINITIONSHAPE($,$,(#176));\n\
         #150=IFCBUILDINGELEMENTPROXY('0000000000000000000150',$,$,$,$,#3,#177,$,$);\n",
        body(
            143,
            58.5,
            1.0,
            1.0,
            "IFCMEMBER('0000000000000000000149',$,$,$,$,#3,REP,$,.MEMBER.)",
        ),
        crossed(160, 65.0, 2.0, 1.0),
        crossed(170, 58.2, 1.0, 0.6),
        crossed(173, 65.2, 3.0, 0.6),
    );
    let model = case.write("model.ifc", &spaces_beside_unmeasured_obstacles(&extra));
    let saved = case.path("result.json");
    let output = Command::new(env!("CARGO_BIN_EXE_axioval"))
        .args(["check", "--geometry", "--model"])
        .arg(&model)
        .args([
            "--definitions",
            &format!("{inventory}/definitions.json"),
            "--ruleset",
            &format!("{inventory}/ruleset.json"),
            "--report",
        ])
        .arg(&saved)
        .output()
        .unwrap();
    assert!(
        matches!(output.status.code(), Some(3 | 4)),
        "{}",
        stderr(&output)
    );
    let result: Value = serde_json::from_str(&std::fs::read_to_string(&saved).unwrap()).unwrap();
    let unmeasured = unmeasured_reasons(&result);
    for object in ["#140", "#142", "#150"] {
        assert!(unmeasured.contains_key(object), "{object}: {unmeasured:?}");
    }
    assert!(!unmeasured.contains_key("#149"), "{unmeasured:?}");

    let refused: BTreeMap<String, String> = result["report"]["not_evaluated"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|outcome| outcome["rule_id"] == "space-free-floor")
        .map(|outcome| {
            (
                outcome["object_id"]["local_id"]
                    .as_str()
                    .unwrap()
                    .to_owned(),
                outcome["message"].as_str().unwrap().to_owned(),
            )
        })
        .collect();
    assert_eq!(
        refused.keys().map(String::as_str).collect::<Vec<_>>(),
        ["#16", "#26", "#46"],
        "{refused:#?}"
    );
}

/// An unmeasured obstacle with no sound bound refuses every floor search
/// (#358). Member #120 is a polygonal bounded half-space less a box: a
/// half-space reaches without end below its plane, and this one's boundary
/// cannot exist as written (the wall's #62), so neither the member nor
/// railing #130, made of it, is bounded. Either could be anywhere, so every
/// space's free floor, the one apart from the bounded obstacles included,
/// stays not evaluated rather than deciding.
#[test]
fn with_geometry_an_unmeasured_obstacle_without_a_sound_bound_refuses_every_floor_search() {
    let inventory = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../scripts/inventory");
    let case = Case::new("space-unbounded-obstacle");
    let unbounded = "#121=IFCBOOLEANRESULT(.DIFFERENCE.,#62,#53);\n\
                     #122=IFCSHAPEREPRESENTATION(#5,'Body','CSG',(#121));\n\
                     #123=IFCPRODUCTDEFINITIONSHAPE($,$,(#122));\n\
                     #120=IFCMEMBER('0000000000000000000120',$,$,$,$,#3,#123,$,.MEMBER.);\n\
                     #130=IFCRAILING('0000000000000000000130',$,$,$,$,#3,$,$,.HANDRAIL.);\n\
                     #131=IFCRELAGGREGATES('0000000000000000000131',$,$,$,#130,(#120));\n";
    let model = case.write("model.ifc", &spaces_beside_unmeasured_obstacles(unbounded));
    let saved = case.path("result.json");
    let output = Command::new(env!("CARGO_BIN_EXE_axioval"))
        .args(["check", "--geometry", "--model"])
        .arg(&model)
        .args([
            "--definitions",
            &format!("{inventory}/definitions.json"),
            "--ruleset",
            &format!("{inventory}/ruleset.json"),
            "--report",
        ])
        .arg(&saved)
        .output()
        .unwrap();
    assert!(
        matches!(output.status.code(), Some(3 | 4)),
        "{}",
        stderr(&output)
    );
    let result: Value = serde_json::from_str(&std::fs::read_to_string(&saved).unwrap()).unwrap();
    let unmeasured = unmeasured_reasons(&result);
    assert!(
        unmeasured.contains_key("#120") && unmeasured.contains_key("#130"),
        "{unmeasured:?}"
    );

    // Every space's free floor is refused; the one apart from the bounded
    // obstacles by the unbounded ones.
    for space in ["#16", "#26", "#46", "#96"] {
        let message = result["report"]["not_evaluated"]
            .as_array()
            .unwrap()
            .iter()
            .find(|outcome| {
                outcome["rule_id"] == "space-free-floor"
                    && outcome["object_id"]["local_id"] == space
            })
            .and_then(|outcome| outcome["message"].as_str())
            .unwrap_or_else(|| panic!("{space} decides: {:#}", result["report"]));
        let obstacles: &[&str] = if space == "#96" {
            &["#120", "#130"]
        } else {
            &["#66", "#78", "#80", "#106", "#120", "#130"]
        };
        assert!(
            obstacles
                .iter()
                .any(|obstacle| message.contains(&format!("/{obstacle}"))),
            "{space}: {message}"
        );
    }
}

/// engine#314: a faceted prism 0.03 m high over a pentagon whose corner `v`
/// lies about 0.4 um off the line through its neighbours `a` and `b`
/// (axiolid/kernel#278's repro). The mesh compiler dropped `v` from the top
/// cap only, so three edges bounded one triangle each and the body was an
/// open surface with no volume. Since axiolid-mesh-compile 0.3.16 every
/// corner is kept, the body closes, and its volume is the pentagon's area
/// times its height, and so is the mirrored prism's.
#[test]
fn with_geometry_a_faceted_prism_with_a_nearly_collinear_corner_is_a_closed_solid() {
    let case = Case::new("geometry-nearly-collinear-corner");
    let pentagon: [[f64; 2]; 5] = [
        [0.877_258, 2.548_603],
        [-0.586_191, 1.488_751],
        [0.0, 0.0],
        [0.054_955, -0.139_57],
        [0.183_174, -0.465_204],
    ];
    let height = 0.03;
    let area = (0..5)
        .map(|i| {
            let ([x0, y0], [x1, y1]) = (pentagon[i], pentagon[(i + 1) % 5]);
            x0 * y1 - x1 * y0
        })
        .sum::<f64>()
        / 2.0;
    let prism = |mirrored: bool| {
        // Mirrored in x, the ring is reversed to stay counter-clockwise.
        let ring: Vec<[f64; 2]> = if mirrored {
            pentagon.iter().rev().map(|[x, y]| [-x, *y]).collect()
        } else {
            pentagon.to_vec()
        };
        let mut data = String::new();
        for (index, [x, y]) in ring.iter().enumerate() {
            for (level, z) in [0.0_f64, height].into_iter().enumerate() {
                writeln!(
                    data,
                    "#{}=IFCCARTESIANPOINT(({x:?},{y:?},{z:?}));",
                    100 + 10 * level + index
                )
                .unwrap();
            }
        }
        let (bottom, top) = (|i: usize| 100 + i, |i: usize| 110 + i);
        // Outward: the bottom cap clockwise seen from above, the top cap
        // counter-clockwise, and each side quad.
        let mut faces: Vec<Vec<usize>> = vec![
            (0..5).rev().map(bottom).collect(),
            (0..5).map(top).collect(),
        ];
        for i in 0..5 {
            let j = (i + 1) % 5;
            faces.push(vec![bottom(i), bottom(j), top(j), top(i)]);
        }
        let mut face_ids = Vec::new();
        for (index, face) in faces.iter().enumerate() {
            let [poly, bound, id] = [0, 1, 2].map(|offset| 200 + 3 * index + offset);
            let points: Vec<String> = face.iter().map(|c| format!("#{c}")).collect();
            writeln!(
                data,
                "#{poly}=IFCPOLYLOOP(({}));\n#{bound}=IFCFACEOUTERBOUND(#{poly},.T.);\n\
                 #{id}=IFCFACE((#{bound}));",
                points.join(",")
            )
            .unwrap();
            face_ids.push(format!("#{id}"));
        }
        writeln!(
            data,
            "#240=IFCCLOSEDSHELL(({}));\n#241=IFCFACETEDBREP(#240);\n\
             #242=IFCSHAPEREPRESENTATION(#5,'Body','Brep',(#241));\n\
             #243=IFCPRODUCTDEFINITIONSHAPE($,$,(#242));\n\
             #69=IFCWALL('0000000000000000000069',$,$,$,$,#3,#243,$,$);",
            face_ids.join(",")
        )
        .unwrap();
        model_with(&data)
    };
    let volume = json!({"kind": "property", "propertySet": "axioval:measured",
                        "property": "volume"});
    let cubic = |value: f64| json!({"kind": "literal", "value": {"type": "quantity", "value": value, "unit": "m3"}});
    for mirrored in [false, true] {
        let (output, result) = case.geometry_rule(
            &prism(mirrored),
            &[("wall", "IfcWall")],
            "axioval:capability.expression",
            &registry_signature("axioval:capability.expression"),
            entity("wall"),
            json!({"requirement": {"type": "expression", "value":
                {"kind": "between", "operand": volume,
                 "low": cubic(area * height - 1e-9), "high": cubic(area * height + 1e-9)}}}),
        );
        assert_eq!(output.status.code(), Some(0), "{mirrored}: {result:#}");
        assert_eq!(result["report"]["findings"], json!([]), "{mirrored}");
        assert_eq!(result["report"]["not_evaluated"], json!([]), "{mirrored}");
        assert_eq!(result["geometry"]["exact"], 1, "{mirrored}: {result:#}");
        assert!(
            !result["integrity"]
                .to_string()
                .contains("shape.open-surface"),
            "{mirrored}: {result:#}"
        );
    }
}

/// A deck sectioned along an `IfcOffsetCurve2D` (#90) 1.5 m beside a
/// polyline. Since ifc-geometry 0.20 (openbimrs/ifc#414) stations lower on
/// such an offset basis, where they were refused by name: the deck reaches
/// the mesh compiler, which certifies no bound between stations, and is
/// unmeasured for that.
#[test]
fn with_geometry_stations_on_an_offset_basis_lower() {
    let deck = "#86=IFCCARTESIANPOINT((20.,0.));\n\
                #87=IFCCARTESIANPOINT((40.,0.));\n\
                #84=IFCPOLYLINE((#86,#87));\n\
                #90=IFCOFFSETCURVE2D(#84,1.5,.F.);\n\
                #93=IFCRECTANGLEPROFILEDEF(.AREA.,'narrow',#95,2.,1.);\n\
                #94=IFCRECTANGLEPROFILEDEF(.AREA.,'wide',#95,4.,1.);\n\
                #95=IFCAXIS2PLACEMENT2D(#96,$);\n\
                #96=IFCCARTESIANPOINT((0.,0.));\n\
                #97=IFCAXIS2PLACEMENTLINEAR(#98,$,$);\n\
                #98=IFCPOINTBYDISTANCEEXPRESSION(IFCLENGTHMEASURE(0.),$,$,$,#90);\n\
                #99=IFCAXIS2PLACEMENTLINEAR(#100,$,$);\n\
                #100=IFCPOINTBYDISTANCEEXPRESSION(IFCLENGTHMEASURE(5.),$,$,$,#90);\n\
                #50=IFCSECTIONEDSOLIDHORIZONTAL(#90,(#93,#94),(#97,#99));\n\
                #51=IFCSHAPEREPRESENTATION(#5,'Body','AdvancedSweptSolid',(#50));\n\
                #52=IFCPRODUCTDEFINITIONSHAPE($,$,(#51));\n\
                #53=IFCBUILDINGELEMENTPROXY('0000000000000000000053',$,$,$,$,#3,#52,$,$);\n";
    let case = Case::new("geometry-offset-stations");
    let model =
        crossing_walls_with(deck).replace("FILE_SCHEMA(('IFC4'))", "FILE_SCHEMA(('IFC4X3_ADD2'))");
    let (output, result) = case.wall_clash(&model, &json!({}));
    assert!(output.status.code().is_some(), "{}", stderr(&output));
    let reason = unmeasured_reasons(&result)
        .remove("#53")
        .unwrap_or_else(|| panic!("{result:#}"));
    assert!(
        reason.contains("certifies no bound") && reason.contains("stationed sections"),
        "{reason}"
    );
}

